//! `cargo xtask design-generate`: `design/tokens.json` -> QML
//! singleton `Theme.qml`. `--check` fails (non-zero exit, no write) if the
//! generated file would differ from what's checked in, so CI can catch
//! drift between the token source of truth and the generated code.

use anyhow::{bail, Context, Result};
use serde::Deserialize;
use std::collections::BTreeMap;
use std::path::PathBuf;

/// group -> key -> token definition
#[derive(Debug, Deserialize)]
#[serde(transparent)]
struct TokensFile {
    groups: BTreeMap<String, BTreeMap<String, Token>>,
}

#[derive(Debug, Deserialize)]
struct Token {
    /// Value for light mode (or the only value, for non-color tokens).
    value: String,
    /// Value for dark mode, if this is a colour token with light/dark
    /// variants (Tokens page has light/dark modes).
    #[serde(default)]
    dark: Option<String>,
    /// `text` (WCAG 2.2 AA: 4.5:1), `fill` (non-text, 3:1) or
    /// `background` (row tints text sits on).
    #[serde(default)]
    role: Option<String>,
    /// The QML property name on the `Theme` singleton, e.g. `rowCorrected`
    /// for `color/row-corrected` (the Figma variable's "Code syntax").
    code_syntax: String,
}

pub fn workspace_root() -> Result<PathBuf> {
    let output = std::process::Command::new("cargo")
        .args(["locate-project", "--workspace", "--message-format=plain"])
        .output()
        .context("running cargo locate-project")?;
    let path = String::from_utf8(output.stdout)?.trim().to_string();
    Ok(PathBuf::from(path).parent().unwrap().to_path_buf())
}

pub fn generate(check: bool) -> Result<()> {
    let root = workspace_root()?;
    let tokens_path = root.join("design/tokens.json");
    let qml_path = root.join("design/generated/Theme.qml");

    let text = std::fs::read_to_string(&tokens_path)
        .with_context(|| format!("reading {}", tokens_path.display()))?;
    let tokens: TokensFile = serde_json::from_str(&text)
        .with_context(|| format!("parsing {}", tokens_path.display()))?;

    let problems = contrast_problems(&tokens);
    if !problems.is_empty() {
        bail!(
            "design/tokens.json: contrast below WCAG 2.2 AA:\n  {}",
            problems.join("\n  ")
        );
    }
    let generated = render_qml(&tokens);

    if check {
        let existing = std::fs::read_to_string(&qml_path).unwrap_or_default();
        if existing != generated {
            bail!("design/generated/Theme.qml is out of date with design/tokens.json; run `cargo xtask design-generate` and commit the result");
        }
        println!("design/generate --check: Theme.qml matches tokens.json");
        Ok(())
    } else {
        std::fs::create_dir_all(qml_path.parent().unwrap())?;
        std::fs::write(&qml_path, &generated)?;
        println!("wrote {}", qml_path.display());
        Ok(())
    }
}

fn render_qml(tokens: &TokensFile) -> String {
    let mut light = String::new();
    let mut dark = String::new();
    let mut count = 0usize;
    for (group, entries) in &tokens.groups {
        for (key, token) in entries {
            count += 1;
            light.push_str(&format!(
                "        // {group}/{}\n        readonly property color {} : \"{}\"\n",
                key.replace('_', "-"),
                token.code_syntax,
                token.value
            ));
            let dark_value = token.dark.as_deref().unwrap_or(&token.value);
            dark.push_str(&format!(
                "        readonly property color {} : \"{}\"\n",
                token.code_syntax, dark_value
            ));
        }
    }
    let _ = count;
    format!(
        "// GENERATED by `cargo xtask design-generate` from design/tokens.json.\n// Do not edit by hand; edit tokens.json (or the Figma variables it\n// mirrors) and regenerate.\npragma Singleton\nimport QtQuick\n\nQtObject {{\n    id: theme\n\n    // The token set for a page's background: Theme.of(Kirigami.Theme.backgroundColor).\n    function of(background: color): QtObject {{ return background.hslLightness < 0.5 ? theme.dark : theme.light }}\n\n    readonly property QtObject light: QtObject {{\n{light}    }}\n\n    readonly property QtObject dark: QtObject {{\n{dark}    }}\n}}\n"
    )
}

/// Breeze's view and window backgrounds that tokens are drawn on: light,
/// then dark.
const LIGHT_BACKGROUNDS: [&str; 2] = ["#FFFFFF", "#EFF0F1"];
const DARK_BACKGROUNDS: [&str; 3] = ["#141618", "#1B1E20", "#202326"];

fn luminance(hex: &str) -> f64 {
    // `#AARRGGBB` or `#RRGGBB`: the colour is the last six digits.
    let hex = &hex[hex.len() - 6..];
    let channel = |i: usize| {
        let c = f64::from(u8::from_str_radix(&hex[i..i + 2], 16).unwrap_or(0)) / 255.0;
        if c <= 0.04045 {
            c / 12.92
        } else {
            ((c + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * channel(0) + 0.7152 * channel(2) + 0.0722 * channel(4)
}

/// WCAG 2.2's contrast ratio.
fn contrast(a: &str, b: &str) -> f64 {
    let (a, b) = (luminance(a), luminance(b));
    (a.max(b) + 0.05) / (a.min(b) + 0.05)
}

/// Every `text` token against every background it can sit on
/// (the page backgrounds and the `background` tokens), in light and dark;
/// `fill` tokens against the page backgrounds at 3:1.
fn contrast_problems(tokens: &TokensFile) -> Vec<String> {
    let all: Vec<(&String, &Token)> = tokens.groups.values().flat_map(|g| g.iter()).collect();
    let mut problems = vec![];
    for dark in [false, true] {
        let value = |t: &Token| match dark {
            true => t.dark.clone().unwrap_or_else(|| t.value.clone()),
            false => t.value.clone(),
        };
        let pages: Vec<String> = match dark {
            true => DARK_BACKGROUNDS.iter().map(|s| s.to_string()).collect(),
            false => LIGHT_BACKGROUNDS.iter().map(|s| s.to_string()).collect(),
        };
        let tints: Vec<String> = all
            .iter()
            .filter(|(_, t)| t.role.as_deref() == Some("background"))
            .map(|(_, t)| value(t))
            .collect();
        for (key, token) in &all {
            let (minimum, backgrounds) = match token.role.as_deref() {
                Some("text") => (4.5, pages.iter().chain(&tints).collect::<Vec<_>>()),
                Some("fill") => (3.0, pages.iter().collect()),
                _ => continue,
            };
            let colour = value(token);
            for background in backgrounds {
                let ratio = contrast(&colour, background);
                if ratio < minimum {
                    let mode = if dark { "dark" } else { "light" };
                    problems.push(format!(
                        "{key} ({mode}) {colour} on {background}: {ratio:.2}:1, needs {minimum}:1"
                    ));
                }
            }
        }
    }
    problems
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tokens(json: &str) -> TokensFile {
        serde_json::from_str(json).unwrap()
    }
    #[test]
    fn the_checked_in_tokens_meet_aa() {
        let text = include_str!("../../design/tokens.json");
        assert_eq!(contrast_problems(&tokens(text)), Vec::<String>::new());
    }

    /// Breeze's #F67400 on white is the 2.8:1 the QA report measured.
    #[test]
    fn a_failing_pair_is_rejected() {
        let t = tokens(
            r##"{"color": {
                "warn": {"value": "#F67400", "role": "text", "code_syntax": "warn"},
                "tint": {"value": "#FFFFFF", "dark": "#3A2A1A", "role": "background", "code_syntax": "tint"}
            }}"##,
        );
        let problems = contrast_problems(&t);
        assert!(
            problems
                .iter()
                .any(|p| p.starts_with("warn (light) #F67400 on #FFFFFF: 2.")),
            "{problems:?}"
        );
        assert!((contrast("#000000", "#FFFFFF") - 21.0).abs() < 1e-9);
    }
}
